const j = $json;
const body = (j.body && typeof j.body === 'object') ? j.body : {};
const raw = j.chatInput ?? body.chatInput ?? body.message ?? body.text ?? j.message ?? j.text ?? '';
const hex = len => Array.from({ length: len }, () => Math.floor(Math.random() * 16).toString(16)).join('');
let source = 'subworkflow';
if (j.test_id || j.testId) source = 'eval';
else if (j.chatInput !== undefined) source = 'chat';
else if (j.body) source = 'webhook';
return {
  json: {
    chatInput: String(raw),
    testId: j.testId ?? j.test_id ?? body.test_id ?? 'chat',
    expected: j.expected ?? '',
    session_id: String(j.sessionId ?? body.sessionId ?? `exec-${$execution.id}`),
    source,
    trace_id: hex(32),
    received_at: new Date().toISOString(),
    started_ms: Date.now(),
  },
};

const MAX_LEN = 1000;
return $input.all().map(item => {
  const j = item.json;
  let t = String(j.chatInput ?? '');
  const originalLength = t.length;
  t = t.normalize('NFKC')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
  const flags = [];
  if (!t) flags.push('empty');
  if (t.length > MAX_LEN) { t = t.slice(0, MAX_LEN); flags.push('truncated'); }
  if (/ignore (all |any )?(previous|prior|above) (instructions|rules)|reveal (your )?system prompt|you are now/i.test(t)) flags.push('possible_prompt_injection');
  // LangChain prompt templates treat curly braces as variables, so swap them out.
  t = t.replace(/\{/g, '(').replace(/\}/g, ')');
  return { json: { ...j, chatInput: t, inputFlags: flags, originalLength } };
});

