function parseCSV(text) {
  const rows = []; let row = [], cur = '', q = false;
  text = text.replace(/^\uFEFF/, '');
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"') { if (text[i+1] === '"') { cur += '"'; i++; } else q = false; } else cur += c; }
    else if (c === '"') q = true;
    else if (c === ',') { row.push(cur); cur = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && text[i+1] === '\n') i++; row.push(cur); cur = ''; if (row.some(x => x.trim() !== '')) rows.push(row); row = []; }
    else cur += c;
  }
  if (cur !== '' || row.length) { row.push(cur); if (row.some(x => x.trim() !== '')) rows.push(row); }
  if (!rows.length) return [];
  const h = rows[0].map(x => x.trim());
  return rows.slice(1).map(r => { const o = {}; h.forEach((k, j) => o[k] = (r[j] || '').trim()); return o; });
}

const tasks = parseCSV(taskCsv);
const timelineRows = parseCSV(timelineCsv);
const inputs = $('Input Hygiene').all();
const addDays = (d, n) => new Date(d.getTime() + n * 86400000);
const iso = d => d.toISOString().slice(0, 10);
const start0 = new Date(PROJECT_START_DATE + 'T00:00:00Z');

function datedTimeline(asOf) {
  if (!timelineRows.length) return null;
  const a14 = iso(addDays(new Date(asOf + 'T00:00:00Z'), 14));
  const phases = timelineRows.map(r => {
    const sw = parseInt(r.start_week, 10), ew = parseInt(r.end_week, 10);
    const ds = iso(addDays(start0, (sw - 1) * 7)), de = iso(addDays(start0, ew * 7 - 1));
    return { phase: r.phase, name: r.phase_name, weeks: 'Week ' + sw + '-' + ew, derivedStart: ds, derivedEnd: de,
      keyActivities: r.key_activities, milestonesDeliverables: r.milestones_deliverables,
      statusAtAsOfDate: de < asOf ? 'ended' : (ds > asOf ? 'not started' : 'in progress') };
  });
  return {
    note: 'Calendar dates are DERIVED from an assumed Week-1 start of ' + PROJECT_START_DATE + '; the CSV itself only has week numbers.',
    phases,
    currentPhase: phases.find(p => p.statusAtAsOfDate === 'in progress') || null,
    milestonesDueNext14Days: phases.filter(p => p.derivedEnd >= asOf && p.derivedEnd <= a14)
      .map(p => ({ phase: p.name, derivedDueDate: p.derivedEnd, milestonesDeliverables: p.milestonesDeliverables }))
  };
}

function computeStats(rows, asOf) {
  if (!rows.length) return null;
  const keys = Object.keys(rows[0]);
  const fk = re => keys.find(k => re.test(k)) || null;
  const K = {
    status: fk(/status/i), due: fk(/due/i), id: fk(/^(task[ _-]?)?id$/i),
    name: fk(/^(task[ _-]?)?(name|title)$|^task$|summary/i), sprint: fk(/sprint/i),
    assignee: fk(/assign|owner/i), priority: fk(/priorit/i), description: fk(/descr/i), labels: fk(/label/i)
  };
  const cat = s => { s = (s || '').toLowerCase().replace(/[_-]/g, ' ');
    if (/done|complete|closed/.test(s)) return 'Done';
    if (/block/.test(s)) return 'Blocked';
    if (/progress|doing/.test(s)) return 'In Progress';
    return 'To Do'; };
  const asOfD = new Date(asOf + 'T00:00:00Z');
  const in14 = addDays(asOfD, 14);
  const g = (r, k) => (k ? r[k] : '');
  const slim = r => ({ id: g(r, K.id), name: g(r, K.name), status: g(r, K.status), sprint: g(r, K.sprint), assignee: g(r, K.assignee), priority: g(r, K.priority), labels: g(r, K.labels), due: g(r, K.due) });
  const counts = { Done: 0, 'In Progress': 0, Blocked: 0, 'To Do': 0 };
  const bySprint = {};
  const blocked = [], inProgress = [], overdue = [], dueWithin14Days = [];
  for (const r of rows) {
    const c = cat(g(r, K.status));
    counts[c]++;
    const sp = K.sprint ? (r[K.sprint] || 'Unassigned') : 'n/a';
    bySprint[sp] = bySprint[sp] || { Done: 0, 'In Progress': 0, Blocked: 0, 'To Do': 0 };
    bySprint[sp][c]++;
    if (c === 'Blocked') blocked.push(Object.assign(slim(r), { blockerNote: g(r, K.description) }));
    if (c === 'In Progress') inProgress.push(slim(r));
    if (c !== 'Done' && K.due && r[K.due]) {
      const d = new Date(r[K.due] + 'T00:00:00Z');
      if (!isNaN(d)) {
        if (d < asOfD) overdue.push(slim(r));
        else if (d <= in14) dueWithin14Days.push(slim(r));
      }
    }
  }
  return { detectedColumns: K, total: rows.length, counts, bySprint, blocked, inProgress, overdue, dueWithin14Days };
}

const out = [];
for (let i = 0; i < inputs.length; i++) {
  const inp = inputs[i].json;
  const m = (inp.chatInput || '').match(/as of (\d{4}-\d{2}-\d{2})/i);
  const asOf = m ? m[1] : (DEFAULT_AS_OF || new Date().toISOString().slice(0, 10));
  const dataSummary = [
    'project_description.txt: ' + (description ? 'loaded' : 'MISSING'),
    'project_timeline.csv: ' + (timelineRows.length ? timelineRows.length + ' phases' : 'MISSING'),
    'project_risks.csv: ' + (risksCsv ? 'loaded' : 'MISSING'),
    'sample_task_board.csv: ' + (tasks.length ? tasks.length + ' tasks' : 'MISSING')
  ].join('; ');
  out.push({ json: {
    chatInput: inp.chatInput, testId: inp.testId || 'chat', expected: inp.expected || '',
    trace_id: inp.trace_id || null, session_id: inp.session_id || null, source: inp.source || 'chat', inputFlags: inp.inputFlags || [],
    asOf, dataSummary, startedAt: inp.started_ms || Date.now(),
    hasData: !!(description || timelineRows.length || risksCsv || tasks.length),
    ctx: { description, timelineCsv, risksCsv, tasks, stats: computeStats(tasks, asOf), dated: datedTimeline(asOf) }
  }});
}
return out;

