const base = $('Build Context (ingest + stats)').all()[$itemIndex].json;

// 1. Read the router's JSON reply (tolerates code fences and extra words)
const raw = String($json.text || '').replace(/```json|```/g, '').trim();
let r = {};
try { r = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { r = { intent: 'clarify' }; }
const valid = ['plan', 'risk', 'status', 'milestone', 'stakeholder', 'clarify'];
if (!valid.includes(r.intent)) r.intent = 'clarify';

// 2. Decide whether this request is about the provided project data
const c = base.ctx;
const routerSaysData = r.uses_provided_data === true || String(r.uses_provided_data).toLowerCase() === 'true';
const namesProject = /abcde|sample task board|task board|provided (project )?description|risk data|project timeline/i.test(base.chatInput || '');
const useData = (routerSaysData || (namesProject && r.intent !== 'clarify')) && base.hasData;

// 3. Sprint filter
const sprintNum = r.sprint ? String(r.sprint).replace(/\D/g, '') : '';
const K = c.stats ? c.stats.detectedColumns : {};
let rows = c.tasks;
if (sprintNum && K.sprint) rows = rows.filter(t => String(t[K.sprint]).replace(/\D/g, '') === sprintNum);
const sprintKey = sprintNum && c.stats ? Object.keys(c.stats.bySprint).find(k => k.replace(/\D/g, '') === sprintNum) : null;

const renderRows = (list) => list.length
  ? Object.keys(list[0]).join(' | ') + '\n' + list.map(t => Object.values(t).join(' | ')).join('\n')
  : '(no rows)';
const J = o => JSON.stringify(o, null, 1);

// 4. Build the data block for the chosen agent
let block;
if (!useData) {
  block = 'PROJECT DATA: NO PROJECT DATA ATTACHED. Only the user\'s own words above are available.';
} else {
  const parts = ['PROJECT DATA (as-of date ' + base.asOf + ')'];
  if (r.intent === 'plan') {
    parts.push('--- project_description.txt ---\n' + c.description);
    parts.push('--- project_timeline.csv (columns: phase, phase_name, start_week, end_week, key_activities, milestones_deliverables; timing is in WEEKS, total 24 weeks) ---\n' + c.timelineCsv);
  } else if (r.intent === 'risk') {
    parts.push('--- project_description.txt ---\n' + c.description);
    parts.push('--- project_risks.csv (no likelihood/severity/rank columns exist) ---\n' + c.risksCsv);
    if (c.stats) parts.push('--- BOARD EVIDENCE (for prioritising / linking risks) ---\nBlocked tasks:\n' + J(c.stats.blocked) + '\nIn-progress tasks:\n' + J(c.stats.inProgress));
    if (c.dated && c.dated.currentPhase) parts.push('--- CURRENT PHASE at as-of date ---\n' + J(c.dated.currentPhase));
  } else if (r.intent === 'stakeholder') {
    parts.push('Requested sprint filter: ' + (sprintNum ? 'Sprint ' + sprintNum + ' ONLY' : 'none'));
    parts.push('--- project_description.txt ---\n' + c.description);
    parts.push('--- TASKS IN SCOPE (already filtered; nothing outside this list may be mentioned) ---\n' + renderRows(rows));
    if (sprintKey) parts.push('--- Pre-computed counts for ' + sprintKey + ' ---\n' + J(c.stats.bySprint[sprintKey]));
  } else {
    // status and milestone
    parts.push('Requested sprint filter: ' + (sprintNum ? 'Sprint ' + sprintNum : 'none (whole board)'));
    parts.push('--- PRE-COMPUTED WHOLE-BOARD STATISTICS (authoritative) ---\n' + (c.stats ? J({ total: c.stats.total, counts: c.stats.counts, blocked: c.stats.blocked, overdue: c.stats.overdue, dueWithin14Days: c.stats.dueWithin14Days }) : '(no task board loaded)'));
    if (sprintKey) parts.push('--- PRE-COMPUTED COUNTS FOR ' + sprintKey.toUpperCase() + ' (use these for the summary table) ---\n' + J(c.stats.bySprint[sprintKey]));
    parts.push('--- TASKS IN SCOPE ---\n' + renderRows(rows));
    if (c.dated) parts.push('--- TIMELINE WITH DERIVED DATES ---\n' + J(c.dated));
  }
  block = parts.join('\n\n');
}

// 5. Output
return { json: {
  intent: r.intent, uses_provided_data: useData, sprint: sprintNum || null,
  audience: r.audience || null, reason: r.reason || '',
  chatInput: base.chatInput, testId: base.testId, expected: base.expected,
  trace_id: base.trace_id, session_id: base.session_id, source: base.source, inputFlags: base.inputFlags,
  asOf: base.asOf, startedAt: base.startedAt, contextBlock: block
}};

// Finalize + Build Trace (OpenTelemetry version for Langfuse)
// Mode: Run Once for Each Item
let meta;
try { meta = $('Parse Router Output').item.json; } catch (e) { meta = $('Parse Router Output').first().json; }

const agentNames = { plan: 'Planner Agent', risk: 'Risk Assessor Agent', status: 'Status Reporter Agent', milestone: 'Milestone Tracker Agent', stakeholder: 'Stakeholder Update Agent', clarify: 'Orchestrator' };
const agent = agentNames[meta.intent] || 'Orchestrator';

// ---- Final answer, with a review footer on drafts that may be shared with others ----
let text = String($json.text || '').trim();
if (['plan', 'risk', 'stakeholder'].includes(meta.intent)) {
  text += '\n\n---\n_Generated by Mira (' + agent + '). Draft for PM/TPM review before sharing with stakeholders._';
}

// ---- OpenTelemetry (OTLP/JSON) payload for Langfuse ----
const hex = len => Array.from({ length: len }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const nowMs = Date.now();
const startMs = Number(meta.startedAt) || nowMs;
const nano = ms => String(Math.round(ms)) + '000000'; // milliseconds to nanoseconds, without BigInt
const sv = (k, v) => ({ key: k, value: { stringValue: String(v ?? '') } });

const traceId = (meta.trace_id && /^[0-9a-f]{32}$/.test(meta.trace_id)) ? meta.trace_id : hex(32);
const rootId = hex(16);
const genId = hex(16);
const estIn = Math.round(((meta.contextBlock || '').length + (meta.chatInput || '').length) / 4);
const estOut = Math.round(text.length / 4);

const rootAttrs = [
  sv('langfuse.trace.name', 'mira-run'),
  sv('langfuse.session.id', meta.session_id || ''),
  { key: 'langfuse.trace.tags', value: { arrayValue: { values: [sv('', meta.intent).value, sv('', meta.source || 'chat').value] } } },
  sv('langfuse.trace.input', meta.chatInput),
  sv('langfuse.trace.output', text),
  sv('langfuse.observation.input', meta.chatInput),
  sv('langfuse.observation.output', text),
  sv('langfuse.trace.metadata.intent', meta.intent),
  sv('langfuse.trace.metadata.agent', agent),
  sv('langfuse.trace.metadata.uses_provided_data', meta.uses_provided_data),
  sv('langfuse.trace.metadata.sprint', meta.sprint || ''),
  sv('langfuse.trace.metadata.as_of', meta.asOf),
  sv('langfuse.trace.metadata.testId', meta.testId),
  sv('langfuse.trace.metadata.input_flags', JSON.stringify(meta.inputFlags || [])),
  sv('langfuse.trace.metadata.latency_ms', nowMs - startMs)
];
const genAttrs = [
  sv('langfuse.observation.type', 'generation'),
  sv('gen_ai.request.model', 'gpt-4o-mini'),
  sv('langfuse.observation.input', meta.contextBlock),
  sv('langfuse.observation.output', text),
  sv('langfuse.observation.usage_details', JSON.stringify({ input: estIn, output: estOut })),
  sv('langfuse.observation.metadata.token_counts_are_estimates', 'true')
];

const otel = { resourceSpans: [{
  resource: { attributes: [sv('service.name', 'mira-n8n')] },
  scopeSpans: [{ scope: { name: 'mira' }, spans: [
    { traceId, spanId: rootId, name: 'mira-run', kind: 1, startTimeUnixNano: nano(startMs), endTimeUnixNano: nano(nowMs), attributes: rootAttrs, status: { code: 1 } },
    { traceId, spanId: genId, parentSpanId: rootId, name: agent, kind: 1, startTimeUnixNano: nano(startMs), endTimeUnixNano: nano(nowMs), attributes: genAttrs, status: { code: 1 } }
  ] }]
}] };

return { json: {
  output: text, intent: meta.intent, agent, testId: meta.testId, input: meta.chatInput,
  expected: meta.expected, latencyMs: nowMs - startMs, otel
}};
